// Comprueba el sobre y los campos obligatorios de cada tipo (docs/integracion.md).
// ruta: 0 incompleto, 1 order.created, 2 payment.simulated, 3 order.status_changed, 4 support.requested
const ev = $('Webhook tienda').item.json.body ?? {};
const data = ev.data ?? {};
const REQUIRED = {
  'order.created': ['code'],
  'payment.simulated': ['code', 'status'],
  'order.status_changed': ['code', 'from', 'to'],
  'support.requested': [],
};
const empty = v => v === undefined || v === null || v === '';
const missing = ['type', 'occurred_at'].filter(k => empty(ev[k]));
if (!(Number.isInteger(ev.event_id) && ev.event_id > 0)) missing.unshift('event_id');
if (!empty(ev.type) && !(ev.type in REQUIRED)) missing.push('type');
for (const k of REQUIRED[ev.type] ?? []) if (empty(data[k])) missing.push('data.' + k);

const ruta = missing.length ? 0 : Object.keys(REQUIRED).indexOf(ev.type) + 1;
return { json: { ...ev, data, missing, ruta } };

// Pedido de la tienda -> cuerpo de POST /bo-api/orders (docs/backoffice-api.md)
const o = $json;
return { json: {
  event_id: $('Validar').item.json.event_id,
  code: o.code,
  customer: { name: o.customer.name, email: o.customer.email },
  status: o.status,
  total: o.total,
  placed_at: o.placed_at,
  lines: o.lines.map(l => ({
    product_name: l.product_name,
    game: l.game ?? 'Desconocido', // el producto se borró de la tienda
    set_name: l.set_name ?? null,
    card_condition: l.card_condition ?? null,
    language: l.language ?? null,
    is_foil: l.is_foil ?? false,
    quantity: l.quantity,
    unit_price: l.unit_price,
    line_total: l.line_total,
  })),
} };

// Error de la tienda: la red o un 5xx se reintentan (pendiente); un 4xx no se arregla reintentando (error)
const err = $json.error ?? {};
const status = Number(err.httpCode ?? String(err.message ?? '').match(/^(\d{3})/)?.[1] ?? 0);
const map = {
  401: ['error', 'clave_no_valida'],
  404: ['error', 'pedido_no_existe_en_tienda'],
};
const [result, error_type] = map[status] ?? (status >= 400 && status < 500 ? ['error', 'datos_no_validos'] : ['pendiente', 'tienda_no_disponible']);
return { json: { result, error_type, message: String(err.message ?? 'La tienda no respondió').slice(0, 500) } };

// Error del back-office: 404 = el pedido aún no está (se reintenta), 422/401 = no se reintenta
const err = $json.error ?? {};
const status = Number(err.httpCode ?? String(err.message ?? '').match(/^(\d{3})/)?.[1] ?? 0);
const map = {
  404: ['pendiente', 'pedido_no_existe'],
  422: ['error', 'datos_no_validos'],
  401: ['error', 'clave_no_valida'],
};
const [result, error_type] = map[status] ?? ['pendiente', 'backoffice_no_disponible'];
return { json: { result, error_type, message: String(err.message ?? 'El back-office no respondió').slice(0, 500) } };
